<?php
namespace Azula\SmsStudio;
/** Bounded/indexed SMS-owned event projections. No customer/order/provider writes. */
final class M8Analytics
{
    public const GRACE=86400;
    public function __construct(private M6Store $s){}
    private static function blank():array{return ['events'=>0,'known_unique'=>0,'unmatched'=>0,'known_minor'=>0,'missing_values'=>0];}
    private static function finish(array $a):array{$a['unique_recipients']=$a['unmatched']?null:$a['known_unique'];$a['value_minor']=$a['missing_values']||$a['known_minor']===null?null:$a['known_minor'];return $a;}
    public function decorate(array $report,string $filter):array
    {
        $s=$this->s;$c=$s->table('campaigns');$m=$s->table('campaign_meta');$e=$s->table('journey');$k=$s->table('clicks');$r=$s->table('recipient_links');$v=$s->table('conversions');$from=(int)$report['range']['start_utc'];$to=(int)$report['range']['end_utc'];$scope=" INNER JOIN $c c ON c.id=e.campaign_id LEFT JOIN $m m ON m.campaign_id=c.id LEFT JOIN $k event_click ON event_click.id=e.click_id LEFT JOIN $r event_map ON event_map.id=event_click.recipient_link_id AND event_map.campaign_id=e.campaign_id WHERE $filter";$effective="COALESCE(NULLIF(e.recipient_id,0),event_map.recipient_id)";
        $groups=$s->rows("SELECT e.campaign_id,e.kind,COUNT(*) events,COUNT(DISTINCT $effective) known_unique,SUM(CASE WHEN $effective IS NULL THEN 1 ELSE 0 END) unmatched,SUM(CASE WHEN e.value_minor IS NOT NULL AND e.currency='EGP' THEN e.value_minor ELSE 0 END) known_minor,SUM(CASE WHEN e.value_minor IS NULL OR e.currency<>'EGP' THEN 1 ELSE 0 END) missing_values FROM $e e$scope AND e.occurred_at>=%d AND e.occurred_at<%d GROUP BY e.campaign_id,e.kind",$from,$to);
        $sent=$s->rows("SELECT a.campaign_id FROM ".$s->table('attempts')." a INNER JOIN $c c ON c.id=a.campaign_id LEFT JOIN $m m ON m.campaign_id=c.id WHERE $filter AND a.state IN ('accepted','rejected','unknown') AND a.claimed_at>=%d AND a.claimed_at<%d GROUP BY a.campaign_id",$from,$to);$sent=array_fill_keys(array_column($sent,'campaign_id'),true);
        $totals=[];$campaigns=[];foreach(['visit','product_view','add_to_cart','checkout_start','purchase'] as $kind)$totals[$kind]=self::blank();
        foreach($groups as $g){$id=(int)$g['campaign_id'];$kind=$g['kind'];if(!isset($totals[$kind]))continue;$metrics=[];foreach(self::blank() as $field=>$unused){$value=(string)$g[$field];if($field==='known_minor'&&(strlen($value)>strlen((string)PHP_INT_MAX)||(strlen($value)===strlen((string)PHP_INT_MAX)&&strcmp($value,(string)PHP_INT_MAX)>0))){$metrics[$field]=null;$totals[$kind][$field]=null;}else{$metrics[$field]=(int)$g[$field];if($field==='known_minor'&&($totals[$kind][$field]===null||$totals[$kind][$field]>PHP_INT_MAX-$metrics[$field]))$totals[$kind][$field]=null;else $totals[$kind][$field]+=$metrics[$field];}}$campaigns[$id][$kind]=$metrics;}
        $purchase=$s->rows("SELECT v.campaign_id,COUNT(*) events,COUNT(DISTINCT r.recipient_id) known_unique,SUM(CASE WHEN r.recipient_id IS NULL THEN 1 ELSE 0 END) unmatched FROM $v v INNER JOIN $c c ON c.id=v.campaign_id LEFT JOIN $m m ON m.campaign_id=c.id LEFT JOIN $k k ON k.id=v.click_id LEFT JOIN $r r ON r.id=k.recipient_link_id AND r.campaign_id=v.campaign_id WHERE $filter AND v.purchase_eligible=1 AND v.order_created>=%d AND v.order_created<%d GROUP BY v.campaign_id",$from,$to);
        foreach($purchase as $g){$a=self::blank();foreach(['events','known_unique','unmatched'] as $key){$a[$key]=(int)$g[$key];$totals['purchase'][$key]+=$a[$key];}$campaigns[(int)$g['campaign_id']]['purchase']=$a;}
        $abandon=$this->abandonment($filter,$from,$to,$totals['checkout_start']['unmatched']);
        foreach($totals as &$a)$a=self::finish($a);unset($a);foreach($report['rows'] as &$row){$row['m8']=['campaigns_sent'=>isset($sent[$row['id']])?1:0];foreach($totals as $kind=>$unused)$row['m8'][$kind]=self::finish($campaigns[(int)$row['id']][$kind]??self::blank());$row['m8']['abandonment']=$abandon['campaigns'][(int)$row['id']]??['potential_minor'=>0,'known_minor'=>0,'potential_recipients'=>0,'observing'=>0,'uncertain'=>0,'latest_checkout_minor'=>0,'latest_known_minor'=>0,'latest_missing'=>0];if(!empty($abandon['limited'])||$row['m8']['checkout_start']['unmatched']){$row['m8']['abandonment']['potential_minor']=null;$row['m8']['abandonment']['uncertain']+=$row['m8']['checkout_start']['unmatched'];$row['m8']['abandonment']['latest_checkout_minor']=null;}}unset($row);
        $report['m8']=['events'=>$totals,'abandonment'=>$abandon['totals'],'definitions'=>['unique'=>'Distinct SMS-owned campaign-recipient records, not Woo customers or verified individuals. Unknown legacy associations are unavailable, not zero.','cart'=>'Added quantity at current catalog/sale price, excluding tax, shipping and cart-level coupons.','checkout'=>'Woo cart payable total after discounts, including shipping/taxes/fees as available at observation; not revenue.','abandonment'=>'Potential only: latest global checkout per campaign-recipient whose latest timestamp is within the selected date cohort, after both 24h inactivity and the full 7-day click window plus 24h grace. Uncertain associations/values/purchases are withheld. Later purchases recompute this projection.','cost'=>'Saved verified provider units only; no EGP conversion.','funnel'=>'Event counts, unique associated records and monetary event sums are different measures; stages are not guaranteed subsets.']];
        if(M9Schema::modern()){$clickGroups=$s->rows("SELECT k.campaign_id,COUNT(DISTINCT NULLIF(r.recipient_id,0)) known,SUM(CASE WHEN r.recipient_id IS NULL OR r.recipient_id=0 THEN 1 ELSE 0 END) unmatched FROM $k k INNER JOIN $c c ON c.id=k.campaign_id LEFT JOIN $m m ON m.campaign_id=c.id LEFT JOIN $r r ON r.id=k.recipient_link_id AND r.campaign_id=k.campaign_id WHERE $filter AND k.observed_at>=%d AND k.observed_at<%d GROUP BY k.campaign_id",$from,$to);$known=0;$missing=0;$clickBy=[];foreach($clickGroups as $g){$known+=(int)$g['known'];$missing+=(int)$g['unmatched'];$clickBy[(int)$g['campaign_id']]=(int)$g['unmatched']?null:(int)$g['known'];}$report['m9']=['unique_clicked_recipients'=>$missing?null:$known,'known_clicked_recipients'=>$known,'unmapped_observations'=>$missing];foreach($report['rows'] as &$row)$row['m9']=['unique_clicked_recipients'=>array_key_exists((int)$row['id'],$clickBy)?$clickBy[(int)$row['id']]:0];unset($row);}
        if(RC1Status::modern())$report=(new RC1Values($s))->decorate($report,$filter);$report['totals']['campaigns_sent']=count($sent);return self::jsonSafeMoney($report);
    }
    private static function jsonSafeMoney(array $value):array
    {
        foreach($value as $key=>&$item){if(is_array($item))$item=self::jsonSafeMoney($item);elseif(is_int($item)&&str_contains((string)$key,'minor')&&$item>9007199254740991)$item=(string)$item;}unset($item);return $value;
    }
    private function abandonment(string $filter,int $from,int $to,int $unmatched):array
    {
        $s=$this->s;$e=$s->table('journey');$c=$s->table('campaigns');$m=$s->table('campaign_meta');$k=$s->table('clicks');$r=$s->table('recipient_links');$v=$s->table('conversions');$zero=['potential_minor'=>0,'known_minor'=>0,'potential_recipients'=>0,'observing'=>0,'uncertain'=>0,'latest_known_minor'=>0,'latest_missing'=>0,'latest_checkout_minor'=>0];$all=$zero;$by=[];
        $events=$s->rows("SELECT e.*,COALESCE(NULLIF(e.recipient_id,0),event_map.recipient_id) tracked_recipient,k.clicked_at FROM $e e INNER JOIN $c c ON c.id=e.campaign_id LEFT JOIN $m m ON m.campaign_id=c.id INNER JOIN $k k ON k.id=e.click_id LEFT JOIN $r event_map ON event_map.id=k.recipient_link_id AND event_map.campaign_id=e.campaign_id WHERE $filter AND e.kind='checkout_start' AND COALESCE(NULLIF(e.recipient_id,0),event_map.recipient_id)>0 AND e.occurred_at>=%d AND e.occurred_at<%d AND NOT EXISTS (SELECT newer.id FROM $e newer LEFT JOIN $k newer_click ON newer_click.id=newer.click_id LEFT JOIN $r newer_map ON newer_map.id=newer_click.recipient_link_id AND newer_map.campaign_id=newer.campaign_id WHERE newer.campaign_id=e.campaign_id AND COALESCE(NULLIF(newer.recipient_id,0),newer_map.recipient_id)=COALESCE(NULLIF(e.recipient_id,0),event_map.recipient_id) AND newer.kind='checkout_start' AND (newer.occurred_at>e.occurred_at OR (newer.occurred_at=e.occurred_at AND newer.id>e.id))) ORDER BY e.id LIMIT 5001",$from,$to);
        $orders=$s->rows("SELECT v.*,r.recipient_id FROM $v v INNER JOIN $c c ON c.id=v.campaign_id LEFT JOIN $m m ON m.campaign_id=c.id INNER JOIN $k k ON k.id=v.click_id LEFT JOIN $r r ON r.id=k.recipient_link_id AND r.campaign_id=v.campaign_id WHERE $filter ORDER BY v.id LIMIT 10001");
        if(count($events)>5000||count($orders)>10000){$zero['potential_minor']=null;$zero['latest_checkout_minor']=null;return ['totals'=>$zero+['reason'=>'Bounded abandonment projection exceeded; narrow filters.'],'campaigns'=>[],'limited'=>true];}
        $purchases=[];foreach($orders as $o){$key=$o['campaign_id'].':'.($o['recipient_id']??0);$purchases[$key][]=$o;}
        $contracts=M6AttributionContracts::available()&&M6AttributionContracts::exclusions()!==null;
        foreach($events as $event){$id=(int)$event['campaign_id'];$key=$id.':'.$event['tracked_recipient'];$row=$by[$id]??$zero;$matched=false;$uncertain=!empty($purchases[$id.':0']);if($event['value_minor']!==null&&$event['currency']==='EGP'){$row['latest_known_minor']+=(int)$event['value_minor'];$all['latest_known_minor']+=(int)$event['value_minor'];}else{$row['latest_missing']++;$all['latest_missing']++;}$row['latest_checkout_minor']=$row['latest_missing']?null:$row['latest_known_minor'];
            foreach($purchases[$key]??[] as $o){if((int)$o['purchase_eligible']===1||$o['reason']==='fully_refunded'){$matched=true;break;}$uncertain=true;}
            if(M9Schema::modern()){$m9=M9Checkout::classify($event,array_merge($purchases[$key]??[],$purchases[$id.':0']??[]));$matched=$m9['state']==='completed';$uncertain=$m9['state']==='uncertain';}
            if($matched){$by[$id]=$row;continue;}
            if(!$contracts||!M6Tracking::enabled()||$uncertain||$event['value_minor']===null||$event['currency']!=='EGP'||!preg_match('/^[a-f0-9]{64}$/D',$event['session_hash']??'')||(int)$event['occurred_at']<(int)$event['clicked_at']||(int)$event['occurred_at']>(int)$event['clicked_at']+M6Tracking::WINDOW){$row['uncertain']++;$all['uncertain']++;}
            elseif(time()<max((int)$event['occurred_at']+self::GRACE,(int)$event['clicked_at']+M6Tracking::WINDOW+self::GRACE)){$row['observing']++;$all['observing']++;}
            else{$row['known_minor']+=(int)$event['value_minor'];$row['potential_recipients']++;$all['known_minor']+=(int)$event['value_minor'];$all['potential_recipients']++;}
            $row['potential_minor']=$row['uncertain']?null:$row['known_minor'];$by[$id]=$row;
        }
        $all['latest_missing']+=$unmatched;$all['latest_checkout_minor']=$all['latest_missing']?null:$all['latest_known_minor'];$all['uncertain']+=$unmatched;$all['potential_minor']=$all['uncertain']?null:$all['known_minor'];return ['totals'=>$all,'campaigns'=>$by];
    }
}
